 }  // QuickTimeVideo::decodeBlock

 static std::string readString(BasicIo& io, size_t size) {
-  enforce(size <= io.size() - io.tell(), Exiv2::ErrorCode::kerCorruptedMetadata);
-  Exiv2::DataBuf str(size + 1);
-  io.readOrThrow(str.data(), size);
-  str.write_uint8(size, 0);  // nul-terminate string
-  return Exiv2::toString(str.data());
+  // The block sizes handed down by decodeBlock() are already bounded by the
+  // stream size, so read the string straight out of the mapped buffer
+  // instead of copying it through a temporary nul-terminated buffer.
+  const auto* begin = reinterpret_cast<const char*>(io.mmap()) + io.tell();
+  size_t len = 0;
+  while (len < size && begin[len] != '\0')
+    ++len;
+  std::string str(begin, len);
+  io.seek(io.tell() + size, BasicIo::beg);
+  return str;
 }

